findings.codeql_raw_query:
/**
 * @name Untrusted data in file system operations in tqdm
 * @description Detects flows from remote/user-controlled sources into file path arguments within tqdm.
 * @kind path-problem
 * @problem.severity error
 * @id py/tqdm-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module TqdmFsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module TqdmFsFlow = TaintTracking::Global<TqdmFsConfig>;
import TqdmFsFlow::PathGraph

from TqdmFsFlow::PathNode source, TqdmFsFlow::PathNode sink
where TqdmFsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a file system path in tqdm ($@).", source.getNode(), "user input"
